  "CG": { year: 1960, event: "The Republic of the Congo became independent from France on 15 August 1960", source: "https://en.wikipedia.org/wiki/History_of_the_Republic_of_the_Congo" },
  "CI": { year: 1960, event: "Ivory Coast became independent from France on 7 August 1960", source: "https://en.wikipedia.org/wiki/History_of_Ivory_Coast" },
  "CL": { year: 1818, event: "Declaration of Independence from Spain, proclaimed 12 February 1818", source: "https://en.wikipedia.org/wiki/Chilean_Declaration_of_Independence" },
  "CM": { year: 1960, event: "French Cameroun became independent on 1 January 1960", note: "The southern part of British Cameroons joined it in October 1961 to form a federal republic; the northern part joined Nigeria.", source: "https://en.wikipedia.org/wiki/History_of_Cameroon" },
  "CO": { year: 1810, event: "Declaration of independence from Spain at Bogotá, 20 July 1810", note: "Independence was secured militarily at Boyacá in 1819, and the present republic separated from Gran Colombia in 1831.", source: "https://en.wikipedia.org/wiki/Colombian_Declaration_of_Independence" },
  "CR": { year: 1838, event: "Costa Rica withdrew from the Federal Republic of Central America on 14 November 1838 and became a sovereign state", note: "Central America had declared independence from Spain on 15 September 1821, but Costa Rica then belonged to the First Mexican Empire until 1823 and to the Central American federation until 1838; a republic was proclaimed in 1848.", source: "https://en.wikipedia.org/wiki/History_of_Costa_Rica" },
  "CU": { year: 1902, event: "The Republic of Cuba proclaimed on 20 May 1902, ending the United States military occupation that followed the 1898 war", source: "https://en.wikipedia.org/wiki/History_of_Cuba" },
  "CV": { year: 1975, event: "Cape Verde became independent from Portugal on 5 July 1975", source: "https://en.wikipedia.org/wiki/History_of_Cape_Verde" },
  "CY": { year: 1960, event: "Independence from the United Kingdom, 16 August 1960", source: "https://en.wikipedia.org/wiki/History_of_Cyprus" },
  "DJ": { year: 1977, event: "Djibouti became independent from France on 27 June 1977, ending French rule over the Territory of the Afars and the Issas", source: "https://en.wikipedia.org/wiki/History_of_Djibouti" },
  "DM": { year: 1978, event: "Dominica became independent from the United Kingdom on 3 November 1978", source: "https://en.wikipedia.org/wiki/History_of_Dominica" },
  "DO": { year: 1844, event: "The Dominican Republic declared independence on 27 February 1844, separating from Haiti, which had occupied it since 1822", source: "https://en.wikipedia.org/wiki/History_of_the_Dominican_Republic" },
  "DZ": { year: 1962, event: "Independence from France, 5 July 1962, after the eight-year war of independence", source: "https://en.wikipedia.org/wiki/Algerian_War" },
  "EC": { year: 1830, event: "Ecuador seceded from Gran Colombia on 13 May 1830", note: "Independence from Spain had been won at Pichincha in 1822, after which the territory joined Gran Colombia.", source: "https://en.wikipedia.org/wiki/History_of_Ecuador" },
  "EE": { year: 1918, event: "Independence from the Russian Empire declared 24 February 1918", note: "Estonia was occupied and annexed by the Soviet Union in 1940 and restored its independence on 20 August 1991.", source: "https://en.wikipedia.org/wiki/Estonian_Declaration_of_Independence" },
  "EG": { year: 1922, event: "The United Kingdom's unilateral declaration of Egyptian independence, 28 February 1922", note: "British troops remained until 1956, and full sovereignty is often dated to the 1952 revolution and the republic of 1953.", source: "https://en.wikipedia.org/wiki/Unilateral_Declaration_of_Egyptian_Independence" },
  "ER": { year: 1993, event: "Eritrea became independent from Ethiopia on 24 May 1993, after a 1993 referendum confirmed the de facto independence won in 1991", source: "https://en.wikipedia.org/wiki/History_of_Eritrea" },
  "FI": { year: 1917, event: "Finland declared independence from Russia on 6 December 1917, ending over a century as an autonomous Grand Duchy of the Russian Empire", source: "https://en.wikipedia.org/wiki/Finnish_Declaration_of_Independence" },
  "FJ": { year: 1970, event: "Fiji became independent from the United Kingdom on 10 October 1970", source: "https://en.wikipedia.org/wiki/History_of_Fiji" },
  "FM": { year: 1986, event: "The Federated States of Micronesia became a sovereign state in free association with the United States on 3 November 1986, ending the US-administered Trust Territory of the Pacific Islands", source: "https://en.wikipedia.org/wiki/History_of_the_Federated_States_of_Micronesia" },
  "GA": { year: 1960, event: "Gabon became independent from France on 17 August 1960", source: "https://en.wikipedia.org/wiki/History_of_Gabon" },
  "GD": { year: 1974, event: "Grenada became independent from the United Kingdom on 7 February 1974", source: "https://en.wikipedia.org/wiki/History_of_Grenada" },
  "GE": { year: 1918, event: "The Democratic Republic of Georgia declared independence on 26 May 1918", note: "Georgia was invaded and annexed by Soviet Russia in 1921 and restored its independence on 9 April 1991.", source: "https://en.wikipedia.org/wiki/Democratic_Republic_of_Georgia" },
  "GH": { year: 1957, event: "Independence from the United Kingdom, 6 March 1957 — the first colony in sub-Saharan Africa to gain it", source: "https://en.wikipedia.org/wiki/History_of_Ghana" },
  "GM": { year: 1965, event: "The Gambia became independent from the United Kingdom on 18 February 1965", source: "https://en.wikipedia.org/wiki/History_of_the_Gambia" },
  "GN": { year: 1958, event: "Guinea became independent from France on 2 October 1958, the only French African territory to vote No in the 1958 constitutional referendum", source: "https://en.wikipedia.org/wiki/History_of_Guinea" },
  "GQ": { year: 1968, event: "Equatorial Guinea became independent from Spain on 12 October 1968", source: "https://en.wikipedia.org/wiki/History_of_Equatorial_Guinea" },
  "GT": { year: 1821, event: "Guatemala became independent from Spain on 15 September 1821", source: "https://en.wikipedia.org/wiki/History_of_Guatemala" },
  "GU": { year: 1898, event: "Guam was ceded by Spain to the United States in 1898 after the Spanish–American War; it is an unincorporated U.S. Territory. Japan occupied the island from 1941 to 1944", source: "https://en.wikipedia.org/wiki/History_of_Guam" },
  "GW": { year: 1974, event: "Guinea-Bissau's 1973 declaration of independence from Portugal was recognised by Portugal in 1974", source: "https://en.wikipedia.org/wiki/History_of_Guinea-Bissau" },
  "GY": { year: 1966, event: "Independence from the United Kingdom, 26 May 1966", note: "The territory had been Dutch (Essequibo, Demerara and Berbice) before Britain took it in the Napoleonic Wars.", source: "https://en.wikipedia.org/wiki/History_of_Guyana" },
  "HK": { year: 1997, event: "Hong Kong's sovereignty was transferred from the United Kingdom to the People's Republic of China on 1 July 1997, when it became a Special Administrative Region under the 'one country, two systems' principle", source: "https://en.wikipedia.org/wiki/Transfer_of_sovereignty_over_Hong_Kong" },
  "HN": { year: 1821, event: "Honduras became independent from Spain on 15 September 1821", source: "https://en.wikipedia.org/wiki/History_of_Honduras" },
  "HR": { year: 1991, event: "Declaration of independence from Yugoslavia, 25 June 1991", note: "The declaration took effect on 8 October 1991 after a three-month moratorium; international recognition followed in January 1992.", source: "https://en.wikipedia.org/wiki/Croatian_War_of_Independence" },
  "HT": { year: 1804, event: "Haiti declared independence from France on 1 January 1804, becoming the first independent Black republic and the first nation founded by former slaves", source: "https://en.wikipedia.org/wiki/Haitian_Revolution" },
