  "KG": { year: 1991, event: "Kyrgyzstan declared independence from the Soviet Union on 31 August 1991", source: "https://en.wikipedia.org/wiki/History_of_Kyrgyzstan" },
  "KH": { year: 1953, event: "Independence from France, 9 November 1953", note: "Cambodia had been a French protectorate since 1863.", source: "https://en.wikipedia.org/wiki/History_of_Cambodia" },
  "KI": { year: 1979, event: "Kiribati became independent from the United Kingdom on 12 July 1979, ending the Gilbert Islands colony", source: "https://en.wikipedia.org/wiki/History_of_Kiribati" },
  "KM": { year: 1975, event: "The Comoros declared independence from France on 6 July 1975", source: "https://en.wikipedia.org/wiki/History_of_the_Comoros" },
  "KN": { year: 1983, event: "Saint Kitts and Nevis became independent from the United Kingdom on 19 September 1983", source: "https://en.wikipedia.org/wiki/History_of_Saint_Kitts_and_Nevis" },
  "KP": { year: 1948, event: "The Democratic People's Republic of Korea was proclaimed on 9 September 1948; Korea had been liberated from 35 years of Japanese colonial rule in 1945 and the peninsula was then divided into Soviet- and US-administered zones", source: "https://en.wikipedia.org/wiki/History_of_North_Korea" },
  "KR": { year: 1948, event: "The Republic of Korea was established on 15 August 1948; Korea had been liberated from 35 years of Japanese colonial rule in 1945 and divided into US- and Soviet-administered zones", source: "https://en.wikipedia.org/wiki/History_of_South_Korea" },
  "KW": { year: 1961, event: "Independence from the United Kingdom, 19 June 1961", source: "https://en.wikipedia.org/wiki/History_of_Kuwait" },
  "KZ": { year: 1991, event: "Kazakhstan declared independence from the Soviet Union on 16 December 1991", source: "https://en.wikipedia.org/wiki/History_of_Kazakhstan" },
  "LA": { year: 1953, event: "Full independence from France, 22 October 1953", note: "The Kingdom of Laos was succeeded by the Lao People's Democratic Republic in 1975.", source: "https://en.wikipedia.org/wiki/History_of_Laos" },
  "LB": { year: 1943, event: "Lebanon became fully independent from France on 22 November 1943, ending the French mandate over Greater Lebanon", source: "https://en.wikipedia.org/wiki/History_of_Lebanon" },
  "LC": { year: 1979, event: "Saint Lucia became independent from the United Kingdom on 22 February 1979", source: "https://en.wikipedia.org/wiki/History_of_Saint_Lucia" },
  "LK": { year: 1948, event: "Ceylon (now Sri Lanka) became independent from the United Kingdom on 4 February 1948", source: "https://en.wikipedia.org/wiki/British_Ceylon" },
  "LR": { year: 1847, event: "Liberia declared independence on 26 July 1847, the first republic founded by freed people from the United States", source: "https://en.wikipedia.org/wiki/History_of_Liberia" },
  "LS": { year: 1966, event: "Lesotho became independent from the United Kingdom on 4 October 1966, ending the Basutoland protectorate", source: "https://en.wikipedia.org/wiki/History_of_Lesotho" },
  "LT": { year: 1918, event: "Lithuania restored its statehood on 16 February 1918", note: "Lithuania was occupied and annexed by the Soviet Union in 1940 and restored its independence on 11 March 1990.", source: "https://en.wikipedia.org/wiki/Act_of_Independence_of_Lithuania" },
  "LU": { year: 1839, event: "The Treaty of London of 1839 established Luxembourg as an independent grand duchy", note: "Full sovereignty and neutrality were confirmed by the second Treaty of London in 1867.", source: "https://en.wikipedia.org/wiki/History_of_Luxembourg" },
  "LV": { year: 1918, event: "Independence proclaimed 18 November 1918", note: "Latvia was occupied and annexed by the Soviet Union in 1940 and restored its independence on 21 August 1991.", source: "https://en.wikipedia.org/wiki/History_of_Latvia" },
  "LY": { year: 1951, event: "Libya became independent as the United Kingdom of Libya on 24 December 1951", source: "https://en.wikipedia.org/wiki/History_of_Libya" },
  "MA": { year: 1956, event: "Morocco regained independence from France on 2 March 1956, and from Spain later that year, ending the protectorates established in 1912", source: "https://en.wikipedia.org/wiki/French_protectorate_in_Morocco" },
  "MD": { year: 1991, event: "Moldova declared independence from the Soviet Union on 27 August 1991", source: "https://en.wikipedia.org/wiki/History_of_Moldova" },
  "ME": { year: 1878, event: "Montenegro's independence was recognised by the Great Powers at the Congress of Berlin in 1878", note: "Montenegro had been a de-facto sovereign principality for centuries; it was absorbed into Yugoslavia in 1918 and regained independence from the state union with Serbia on 3 June 2006.", source: "https://en.wikipedia.org/wiki/History_of_Montenegro" },
  "MG": { year: 1960, event: "Madagascar became fully independent from France on 26 June 1960", source: "https://en.wikipedia.org/wiki/History_of_Madagascar" },
  "MH": { year: 1986, event: "The Marshall Islands became a sovereign state in free association with the United States on 21 October 1986, ending the US-administered Trust Territory of the Pacific Islands", source: "https://en.wikipedia.org/wiki/History_of_the_Marshall_Islands" },
  "MK": { year: 1991, event: "Macedonia declared independence from Yugoslavia on 8 September 1991", note: "It was admitted to the UN in 1993 as \"the former Yugoslav Republic of Macedonia\" and renamed North Macedonia in 2019 under the Prespa agreement with Greece.", source: "https://en.wikipedia.org/wiki/Independence_of_North_Macedonia" },
