  "MW": { year: 1964, event: "Malawi became independent from the United Kingdom on 6 July 1964, ending the Nyasaland protectorate", source: "https://en.wikipedia.org/wiki/History_of_Malawi" },
  "MX": { year: 1821, event: "Mexico achieved independence from Spain on 27 September 1821 with the Treaty of Córdoba, after the war of independence begun in 1810", source: "https://en.wikipedia.org/wiki/Mexican_War_of_Independence" },
