  "PH": { year: 1946, event: "Independence recognised by the United States under the Treaty of Manila, 4 July 1946", note: "Independence had first been declared from Spain on 12 June 1898 — the date the country now observes — but the islands passed to American administration that same year.", source: "https://en.wikipedia.org/wiki/Treaty_of_Manila_(1946)" },
  "PK": { year: 1947, event: "Pakistan became independent from the United Kingdom on 14 August 1947 at the partition of British India", source: "https://en.wikipedia.org/wiki/Partition_of_India" },
  "PR": { year: 1898, event: "Puerto Rico was ceded by Spain to the United States in 1898 after the Spanish–American War; it is today a U.S. Commonwealth (Estado Libre Asociado)", source: "https://en.wikipedia.org/wiki/History_of_Puerto_Rico" },
  "PS": { year: 1988, event: "The Palestinian Declaration of Independence proclaimed the State of Palestine on 15 November 1988; the territory had been the British Mandate for Palestine from 1920 to 1948", source: "https://en.wikipedia.org/wiki/Palestinian_Declaration_of_Independence" },
  "PW": { year: 1994, event: "Palau became a fully sovereign state on 1 October 1994 under a Compact of Free Association with the United States, ending the US-administered UN Trust Territory of the Pacific Islands; the self-governing Republic had been established in 1981", source: "https://en.wikipedia.org/wiki/History_of_Palau" },
  "PY": { year: 1811, event: "Paraguay declared independence from Spain on 14–15 May 1811", source: "https://en.wikipedia.org/wiki/History_of_Paraguay" },
  "QA": { year: 1971, event: "Independence from the United Kingdom, 3 September 1971", source: "https://en.wikipedia.org/wiki/History_of_Qatar" },
  "RW": { year: 1962, event: "Rwanda became independent from Belgium on 1 July 1962, ending Belgian administration of the Ruanda-Urundi trust territory", source: "https://en.wikipedia.org/wiki/History_of_Rwanda" },
  "SB": { year: 1978, event: "Solomon Islands became independent from the United Kingdom on 7 July 1978", source: "https://en.wikipedia.org/wiki/History_of_Solomon_Islands" },
  "SC": { year: 1976, event: "Seychelles became independent from the United Kingdom on 29 June 1976", source: "https://en.wikipedia.org/wiki/History_of_Seychelles" },
  "SD": { year: 1956, event: "Sudan became independent on 1 January 1956, ending the Anglo-Egyptian condominium", source: "https://en.wikipedia.org/wiki/Anglo-Egyptian_Sudan" },
  "SG": { year: 1965, event: "Separation from Malaysia and full independence, 9 August 1965", note: "Singapore had self-government within the British Empire from 1959 and joined Malaysia in 1963.", source: "https://en.wikipedia.org/wiki/Singapore_in_Malaysia" },
  "SI": { year: 1991, event: "Slovenia declared independence from Yugoslavia on 25 June 1991", source: "https://en.wikipedia.org/wiki/Independence_of_Slovenia" },
  "SL": { year: 1961, event: "Sierra Leone became independent from the United Kingdom on 27 April 1961", source: "https://en.wikipedia.org/wiki/History_of_Sierra_Leone" },
  "SN": { year: 1960, event: "Senegal became independent in 1960, first within the Mali Federation (20 June) and then as a separate republic on 20 August 1960", source: "https://en.wikipedia.org/wiki/History_of_Senegal" },
  "SO": { year: 1960, event: "Somalia became independent on 1 July 1960, uniting the former British Somaliland and the Italian Trust Territory of Somalia", source: "https://en.wikipedia.org/wiki/History_of_Somalia" },
